<?php
namespace App\Http\Controllers\Admin;
use App\Http\Controllers\Controller;use App\Models\CmsEntry;use Illuminate\Http\Request;use Illuminate\Validation\Rule;use Illuminate\Support\Facades\{DB,Storage};
class CmsController extends Controller {
 private function validType(string $type):string {abort_unless(in_array($type,['pages','posts','categories','gallery','services','faqs','banners','homepage_sections'],true),404);return $type;}
 public function index(Request $r,string $type){$v=$r->validate(['status'=>'nullable|in:draft,published','q'=>'nullable|string|max:120','per_page'=>'nullable|integer|min:1|max:100']);return CmsEntry::where('type',$this->validType($type))->when($v['status']??null,fn($q,$s)=>$q->where('status',$s))->when($v['q']??null,fn($q,$term)=>$q->where(fn($w)=>$w->where('title','like','%'.$term.'%')->orWhere('slug','like','%'.$term.'%')))->orderBy('sort_order')->orderByDesc('updated_at')->paginate($v['per_page']??20);}
 public function publicIndex(Request $r,string $type){$type=$this->validType($type);$v=$r->validate(['q'=>'nullable|string|max:120','category_slug'=>'nullable|string|max:255','per_page'=>'nullable|integer|min:1|max:100']);$query=CmsEntry::where('type',$type)->where('status','published')->where('is_active',true)->whereNotNull('published_at')->where('published_at','<=',now());if(!empty($v['q']))$query->where(fn($q)=>$q->where('title','like','%'.$v['q'].'%')->orWhere('slug','like','%'.$v['q'].'%'));if(!empty($v['category_slug'])){$category=CmsEntry::where('type','categories')->where('slug',$v['category_slug'])->where('status','published')->where('is_active',true)->whereNotNull('published_at')->where('published_at','<=',now())->exists();abort_unless($category,404);$query->where('extra->category_slug',$v['category_slug']);}return $query->orderBy('sort_order')->orderByDesc('published_at')->paginate($v['per_page']??20);}
 public function show(string $type,string $slug){return ['data'=>CmsEntry::where('type',$this->validType($type))->where('slug',$slug)->where('status','published')->where('is_active',true)->whereNotNull('published_at')->where('published_at','<=',now())->firstOrFail()];}
 public function store(Request $r,string $type){$type=$this->validType($type);$v=$r->validate(['title'=>'required|string|max:255','slug'=>['required','alpha_dash','max:255',Rule::unique('cms_entries')->where('type',$type)],'body'=>'nullable|string|max:200000','image'=>'nullable|string|max:2048','extra'=>'nullable|array','extra.category_slug'=>'nullable|string|max:255','status'=>'sometimes|in:draft,published','published_at'=>'nullable|date','is_active'=>'sometimes|boolean','seo_title'=>'nullable|string|max:255','seo_description'=>'nullable|string|max:500','sort_order'=>'sometimes|integer|min:0|max:100000']);if(!empty($v['extra']['category_slug']??null))abort_unless(CmsEntry::where('type','categories')->where('slug',$v['extra']['category_slug'])->exists(),422,'Selected CMS category does not exist.');$status=$v['status']??((bool)($v['is_active']??false)?'published':'draft');$active=$status==='published' && ($v['is_active']??true);$entry=DB::transaction(function()use($type,$v,$status,$active){$this->lockMediaReference($v['image']??null);return CmsEntry::create(['type'=>$type,...$v,'status'=>$status,'is_active'=>$active,'published_at'=>$status==='published'?($v['published_at']??now()):null]);});$this->audit($r,'cms.content_created',$entry,['fields'=>array_keys($v)]);return response()->json(['data'=>$entry],201);}
 public function update(Request $r,string $type,CmsEntry $entry){abort_unless($entry->type===$this->validType($type),404);$v=$r->validate(['title'=>'sometimes|required|string|max:255','slug'=>['sometimes','required','alpha_dash','max:255',Rule::unique('cms_entries')->where('type',$type)->ignore($entry->id)],'body'=>'nullable|string|max:200000','image'=>'nullable|string|max:2048','extra'=>'nullable|array','extra.category_slug'=>'nullable|string|max:255','status'=>'sometimes|in:draft,published','published_at'=>'sometimes|nullable|date','is_active'=>'sometimes|boolean','seo_title'=>'nullable|string|max:255','seo_description'=>'nullable|string|max:500','sort_order'=>'sometimes|integer|min:0|max:100000']);if(!empty($v['extra']['category_slug']??null))abort_unless(CmsEntry::where('type','categories')->where('slug',$v['extra']['category_slug'])->exists(),422,'Selected CMS category does not exist.');$status=$v['status']??$entry->status;if(array_key_exists('is_active',$v)&&!array_key_exists('status',$v))$status=$v['is_active']?'published':'draft';$wasPublished=$entry->status==='published';$publishAt=$v['published_at']??$entry->published_at??now();DB::transaction(function()use($entry,$v,$status,$publishAt,$wasPublished){$this->lockMediaReference($v['image']??$entry->image);$entry->update([...$v,'status'=>$status,'is_active'=>$status==='published'&&($v['is_active']??true),'published_at'=>$status==='published'?$publishAt:null]);if(!$wasPublished&&$status==='published'&&!array_key_exists('published_at',$v))$entry->update(['published_at'=>now()]);});$fresh=$entry->fresh();$this->audit($r,'cms.content_updated',$fresh,['fields'=>array_keys($v)]);return ['data'=>$fresh];}
 public function uploadGalleryImage(Request $r){
  $v=$r->validate(['image'=>'required|image|mimes:jpg,jpeg,png,webp,gif|max:5120']);
  $file=$v['image'];$path=$file->store('cms-media','local');
  $id=DB::table('cms_private_media')->insertGetId(['uploaded_by'=>$r->user()->id,'disk'=>'local','path'=>$path,
   'original_name'=>$file->getClientOriginalName(),'mime_type'=>$file->getMimeType()?:'application/octet-stream','size_bytes'=>$file->getSize(),'created_at'=>now(),'updated_at'=>now()]);
  DB::table('booking_audit_events')->insert(['actor_id'=>$r->user()->id,'action'=>'cms.media_uploaded','details'=>json_encode(['media_id'=>$id]),'created_at'=>now(),'updated_at'=>now()]);
  return response()->json(['data'=>['id'=>$id,'path'=>'/api/content-media/'.$id,'url'=>url('/api/content-media/'.$id),'mime_type'=>$file->getMimeType(),'size'=>$file->getSize()]],201);
 }
 public function mediaIndex(Request $r){$v=$r->validate(['q'=>'nullable|string|max:120','per_page'=>'nullable|integer|min:1|max:100']);$q=DB::table('cms_private_media')->when($v['q']??null,fn($query,$term)=>$query->where('original_name','like','%'.$term.'%'))->orderByDesc('id')->paginate($v['per_page']??30);return response()->json(['data'=>$q]);}
 public function mediaDestroy(Request $r,int $media){return DB::transaction(function()use($r,$media){$row=DB::table('cms_private_media')->where('id',$media)->lockForUpdate()->first();abort_unless($row,404);$publicPath='/api/content-media/'.$media;abort_if(CmsEntry::where('image',$publicPath)->orWhere('image','like','%'.$publicPath)->exists(),409,'Media is referenced by content; remove the reference before deleting it.');$disk=Storage::disk($row->disk);abort_unless($disk->exists($row->path),404);abort_unless($disk->delete($row->path),500,'Media storage deletion failed.');DB::table('cms_private_media')->where('id',$media)->delete();DB::table('booking_audit_events')->insert(['actor_id'=>$r->user()->id,'action'=>'cms.media_deleted','details'=>json_encode(['media_id'=>$media]),'created_at'=>now(),'updated_at'=>now()]);return response()->noContent();},3);}
 public function publicMedia(int $media){$row=DB::table('cms_private_media')->find($media);abort_unless($row&&str_starts_with($row->mime_type,'image/'),404);abort_unless(CmsEntry::where('image','/api/content-media/'.$media)->where('status','published')->where('is_active',true)->whereNotNull('published_at')->where('published_at','<=',now())->exists(),404);return $this->streamMedia($row);}
 public function adminMedia(Request $r,int $media){$row=DB::table('cms_private_media')->find($media);abort_unless($row&&str_starts_with($row->mime_type,'image/'),404);return $this->streamMedia($row);}
 private function streamMedia(object $row){$disk=Storage::disk($row->disk);abort_unless($disk->exists($row->path),404);$stream=$disk->readStream($row->path);abort_unless(is_resource($stream),404);return response()->stream(function()use($stream){fpassthru($stream);if(is_resource($stream))fclose($stream);},200,['Content-Type'=>$row->mime_type,'Content-Length'=>(string)$row->size_bytes,'Content-Disposition'=>'inline; filename="'.addcslashes(basename($row->original_name),'"\\').'"','X-Content-Type-Options'=>'nosniff','Cache-Control'=>'private, max-age=300']);}
 public function destroy(Request $r,string $type,CmsEntry $entry){abort_unless($entry->type===$this->validType($type),404);$id=$entry->id;$entry->delete();$this->audit($r,'cms.content_deleted',$entry,['entry_id'=>$id]);return response()->noContent();}
 private function audit(Request $r,string $action,CmsEntry $entry,array $extra=[]):void{DB::table('booking_audit_events')->insert(['actor_id'=>$r->user()->id,'action'=>$action,'details'=>json_encode(['entry_id'=>$entry->id,'type'=>$entry->type,'slug'=>$entry->slug,...$extra]),'created_at'=>now(),'updated_at'=>now()]);}
 private function lockMediaReference(?string $image):void{if(!$image||!preg_match('#(?:^|/)api/content-media/(\d+)$#',$image,$m))return;$media=DB::table('cms_private_media')->where('id',(int)$m[1])->lockForUpdate()->first();abort_unless($media&&str_starts_with($media->mime_type,'image/'),422,'Referenced media does not exist or is not an image.');}
}
